import React, { useState, useEffect, useMemo, memo, useCallback } from "react";
import { Client } from "../types/api";

interface WorkerMetricsData {
  timestamp: string;
  cpu_usage: number;
  memory_usage: number;
  active_tasks: number;
  completed_tasks: number;
  failed_tasks: number;
  response_time: number;
}

interface WorkerMetricsProps {
  clients: Client[];
}

const MetricChart: React.FC<{
  title: string;
  data: WorkerMetricsData[];
  dataKey: keyof WorkerMetricsData;
  color: string;
  unit?: string;
}> = memo(({ title, data, dataKey, color, unit = "" }) => {
  const { maxValue, minValue, range, points } = useMemo(() => {
    const values = data.map(d => Number(d[dataKey]));
    const max = Math.max(...values);
    const min = Math.min(...values);
    const r = max - min || 1;

    const chartPoints = data.map((point, index) => {
      const x = 40 + (index * 340) / (data.length - 1);
      const value = Number(point[dataKey]);
      const y = 160 - ((value - min) / r) * 120;
      return { x, y, value, timestamp: point.timestamp };
    });

    return { maxValue: max, minValue: min, range: r, points: chartPoints };
  }, [data, dataKey]);

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-4">{title}</h3>
      <div className="relative h-48">
        <svg className="w-full h-full" viewBox="0 0 400 160">
          {/* Grid lines */}
          {[0, 1, 2, 3, 4].map(i => (
            <line
              key={i}
              x1="40"
              y1={40 + i * 30}
              x2="380"
              y2={40 + i * 30}
              stroke="#f3f4f6"
              strokeWidth="1"
            />
          ))}

          {/* Y-axis labels */}
          {[0, 1, 2, 3, 4].map(i => {
            const value = maxValue - (i * range / 4);
            return (
              <text
                key={i}
                x="35"
                y={45 + i * 30}
                textAnchor="end"
                className="text-xs fill-secondary-500"
              >
                {value.toFixed(1)}{unit}
              </text>
            );
          })}

          {/* Chart line */}
          {points.length > 1 && (
            <polyline
              fill="none"
              stroke={color}
              strokeWidth="2"
              points={points.map(p => `${p.x},${p.y}`).join(' ')}
            />
          )}

          {/* Data points */}
          {points.map((point, index) => (
            <circle
              key={index}
              cx={point.x}
              cy={point.y}
              r="3"
              fill={color}
              className="hover:r-4 transition-all cursor-pointer"
            >
              <title>{`${title}: ${point.value}${unit} at ${point.timestamp}`}</title>
            </circle>
          ))}
        </svg>
      </div>
    </div>
  );
}, (prevProps, nextProps) => {
  // Custom comparison for MetricChart
  return prevProps.title === nextProps.title &&
         prevProps.dataKey === nextProps.dataKey &&
         prevProps.color === nextProps.color &&
         prevProps.unit === nextProps.unit &&
         prevProps.data.length === nextProps.data.length &&
         prevProps.data.every((item, index) => 
           item[prevProps.dataKey] === nextProps.data[index]?.[nextProps.dataKey]
         );
});

const WorkerCard: React.FC<{
  client: Client;
  metrics: WorkerMetricsData[];
}> = memo(({ client, metrics }) => {
  const isHealthy = client.is_healthy !== false;
  const currentLoad = client.current_load || 0;
  const maxTasks = client.max_concurrent_tasks || 1;
  const loadPercentage = Math.min((currentLoad / maxTasks) * 100, 100);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'idle': return 'bg-success-100 text-success-800';
      case 'busy': return 'bg-warning-100 text-warning-800';
      case 'overloaded': return 'bg-error-100 text-error-800';
      case 'maintenance': return 'bg-secondary-100 text-secondary-800';
      case 'error': return 'bg-error-100 text-error-800';
      default: return 'bg-secondary-100 text-secondary-800';
    }
  };

  const getLoadColor = () => {
    if (loadPercentage < 50) return 'bg-success-500';
    if (loadPercentage < 80) return 'bg-warning-500';
    return 'bg-error-500';
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-secondary-900">
            {client.client_name || client.client_id}
          </h3>
          <p className="text-sm text-secondary-600">
            {client.client_type === 'worker_api' ? 'API Worker' : 'Worker'}
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(client.worker_status || 'unknown')}`}>
            {client.worker_status || 'Unknown'}
          </span>
          <div className={`w-3 h-3 rounded-full ${isHealthy ? 'bg-success-500' : 'bg-error-500'}`} />
        </div>
      </div>

      {/* Load indicator */}
      <div>
        <div className="flex justify-between text-sm text-secondary-600 mb-1">
          <span>Навантаження</span>
          <span>{currentLoad}/{maxTasks} задач</span>
        </div>
        <div className="w-full bg-secondary-200 rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all duration-300 ${getLoadColor()}`}
            style={{ width: `${loadPercentage}%` }}
          />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="text-center">
          <p className="text-2xl font-bold text-secondary-900">
            {client.stats?.total_tasks || 0}
          </p>
          <p className="text-sm text-secondary-600">Всього задач</p>
        </div>
        <div className="text-center">
          <p className="text-2xl font-bold text-success-600">
            {client.stats?.successful_tasks || 0}
          </p>
          <p className="text-sm text-secondary-600">Успішно</p>
        </div>
        <div className="text-center">
          <p className="text-2xl font-bold text-error-600">
            {client.stats?.failed_tasks || 0}
          </p>
          <p className="text-sm text-secondary-600">Помилки</p>
        </div>
        <div className="text-center">
          <p className="text-2xl font-bold text-primary-600">
            {client.stats?.average_processing_time ? 
              `${client.stats.average_processing_time.toFixed(2)}s` : 'N/A'}
          </p>
          <p className="text-sm text-secondary-600">Сер. час</p>
        </div>
      </div>

      {/* Mini charts */}
      {useMemo(() => {
        if (metrics.length === 0) return null;

        const recentMetrics = metrics.slice(-10);
        const maxActiveTasks = Math.max(...metrics.map(m => m.active_tasks), 1);
        const maxResponseTime = Math.max(...metrics.map(m => m.response_time), 1);

        const activeTasksPoints = recentMetrics.map((point, index) => {
          const x = (index * 180) / Math.max(recentMetrics.length - 1, 1);
          const y = 50 - (point.active_tasks * 40) / maxActiveTasks;
          return `${x + 10},${y + 5}`;
        }).join(' ');

        const responseTimePoints = recentMetrics.map((point, index) => {
          const x = (index * 180) / Math.max(recentMetrics.length - 1, 1);
          const y = 50 - (point.response_time * 40) / maxResponseTime;
          return `${x + 10},${y + 5}`;
        }).join(' ');

        return (
          <div className="grid grid-cols-2 gap-4" key={`mini-charts-${client.client_id}`}>
            <div>
              <p className="text-sm font-medium text-secondary-700 mb-2">Активні задачі</p>
              <div className="h-16 relative">
                <svg className="w-full h-full" viewBox="0 0 200 60">
                  <polyline
                    fill="none"
                    stroke="#3b82f6"
                    strokeWidth="2"
                    points={activeTasksPoints}
                  />
                </svg>
              </div>
            </div>
            <div>
              <p className="text-sm font-medium text-secondary-700 mb-2">Час відповіді</p>
              <div className="h-16 relative">
                <svg className="w-full h-full" viewBox="0 0 200 60">
                  <polyline
                    fill="none"
                    stroke="#10b981"
                    strokeWidth="2"
                    points={responseTimePoints}
                  />
                </svg>
              </div>
            </div>
          </div>
        );
      }, [metrics, client.client_id])}
    </div>
  );
}, (prevProps, nextProps) => {
  // Custom comparison for better performance
  return prevProps.client.client_id === nextProps.client.client_id &&
         prevProps.client.connection_status === nextProps.client.connection_status &&
         prevProps.client.worker_status === nextProps.client.worker_status &&
         prevProps.client.active_tasks_count === nextProps.client.active_tasks_count &&
         prevProps.metrics.length === nextProps.metrics.length &&
         JSON.stringify(prevProps.client.stats) === JSON.stringify(nextProps.client.stats);
});

const WorkerMetrics: React.FC<WorkerMetricsProps> = ({ clients }) => {
  const [selectedWorker, setSelectedWorker] = useState<string | null>(null);
  const [metricsData, setMetricsData] = useState<Record<string, WorkerMetricsData[]>>({});
  const [timeRange, setTimeRange] = useState<'1h' | '6h' | '24h' | '7d'>('1h');

  // Memoize filtered workers to prevent unnecessary re-renders
  const workers = useMemo(() => 
    clients.filter(client => 
      client.client_type === 'worker' || client.client_type === 'worker_api'
    ), [clients]
  );

  const { apiWorkers, regularWorkers } = useMemo(() => ({
    apiWorkers: workers.filter(worker => worker.client_type === 'worker_api'),
    regularWorkers: workers.filter(worker => worker.client_type === 'worker')
  }), [workers]);

  // Memoize worker selection handler
  const handleWorkerSelect = useCallback((workerId: string) => {
    setSelectedWorker(prev => prev === workerId ? null : workerId);
  }, []);

  // Memoize time range change handler
  const handleTimeRangeChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
    setTimeRange(e.target.value as any);
  }, []);

  // Generate stable mock metrics data with memoization
  const stableMetricsData = useMemo(() => {
    const generateStableMetrics = (clientId: string): WorkerMetricsData[] => {
      const now = new Date();
      const points = timeRange === '1h' ? 12 : timeRange === '6h' ? 24 : timeRange === '24h' ? 48 : 168;
      const interval = timeRange === '1h' ? 5 : timeRange === '6h' ? 15 : timeRange === '24h' ? 30 : 60;

      // Use client ID as seed for consistent data
      const seed = clientId.split('').reduce((a, b) => a + b.charCodeAt(0), 0);

      // Base values for each worker (consistent)
      const baseCpu = 30 + (seed % 40);
      const baseMemory = 40 + (seed % 30);
      const baseResponseTime = 0.5 + (seed % 100) / 100;

      return Array.from({ length: points }, (_, i) => {
        const timestamp = new Date(now.getTime() - (points - 1 - i) * interval * 60000);
        const timeOffset = i / points;

        // Generate smooth, predictable curves
        const cpuVariation = Math.sin(timeOffset * Math.PI * 2 + seed) * 15;
        const memoryVariation = Math.cos(timeOffset * Math.PI * 1.5 + seed) * 10;
        const responseVariation = Math.sin(timeOffset * Math.PI * 3 + seed) * 0.5;

        return {
          timestamp: timestamp.toISOString(),
          cpu_usage: Math.max(10, Math.min(90, baseCpu + cpuVariation)),
          memory_usage: Math.max(20, Math.min(80, baseMemory + memoryVariation)),
          active_tasks: Math.max(0, Math.floor(3 + Math.sin(timeOffset * Math.PI * 2 + seed) * 2)),
          completed_tasks: Math.floor(50 + timeOffset * 100 + (seed % 50)),
          failed_tasks: Math.floor(timeOffset * 5 + (seed % 3)),
          response_time: Math.max(0.1, baseResponseTime + responseVariation),
        };
      });
    };

    const newMetricsData: Record<string, WorkerMetricsData[]> = {};
    workers.forEach(worker => {
      newMetricsData[worker.client_id] = generateStableMetrics(worker.client_id);
    });
    return newMetricsData;
  }, [workers.length, timeRange]);

  // Update metrics data only when stable data changes with optimized rendering
  useEffect(() => {
    let rafId: number;
    const timer = setTimeout(() => {
      rafId = requestAnimationFrame(() => {
        setMetricsData(stableMetricsData);
      });
    }, 100); // Small delay to debounce rapid changes

    return () => {
      clearTimeout(timer);
      if (rafId) {
        cancelAnimationFrame(rafId);
      }
    };
  }, [stableMetricsData]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-secondary-900">Метрики Воркерів</h1>
          <p className="text-secondary-600">
            Моніторинг продуктивності та навантаження воркерів
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <select
            value={timeRange}
            onChange={handleTimeRangeChange}
            className="px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
          >
            <option value="1h">Остання година</option>
            <option value="6h">Останні 6 годин</option>
            <option value="24h">Остання доба</option>
            <option value="7d">Останній тиждень</option>
          </select>
        </div>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white rounded-xl shadow-sm p-6">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-primary-100 text-primary-600">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z" />
              </svg>
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">Всього воркерів</p>
              <p className="text-2xl font-bold text-secondary-900">{workers.length}</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-success-100 text-success-600">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">Активні</p>
              <p className="text-2xl font-bold text-secondary-900">
                {workers.filter(w => w.connection_status === 'connected').length}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-warning-100 text-warning-600">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">API Воркери</p>
              <p className="text-2xl font-bold text-secondary-900">{apiWorkers.length}</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-secondary-100 text-secondary-600">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">Активних задач</p>
              <p className="text-2xl font-bold text-secondary-900">
                {workers.reduce((sum, w) => sum + (w.active_tasks_count || 0), 0)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Worker cards */}
      <div>
        <h2 className="text-xl font-semibold text-secondary-900 mb-4">Стандартні Воркери</h2>
        {regularWorkers.length > 0 ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {regularWorkers.map(worker => (
              <WorkerCard
                key={`regular-${worker.client_id}`}
                client={worker}
                metrics={metricsData[worker.client_id] || []}
              />
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm p-8 text-center">
            <p className="text-secondary-500">Немає підключених стандартних воркерів</p>
          </div>
        )}
      </div>

      {/* API Worker cards */}
      <div>
        <h2 className="text-xl font-semibold text-secondary-900 mb-4">API Воркери</h2>
        {apiWorkers.length > 0 ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {apiWorkers.map(worker => (
              <WorkerCard
                key={`api-${worker.client_id}`}
                client={worker}
                metrics={metricsData[worker.client_id] || []}
              />
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm p-8 text-center">
            <p className="text-secondary-500">Немає підключених API воркерів</p>
          </div>
        )}
      </div>

      {/* Detailed charts for selected worker */}
      {selectedWorker && metricsData[selectedWorker] && (
        <div>
          <h2 className="text-xl font-semibold text-secondary-900 mb-4">
            Детальні метрики: {workers.find(w => w.client_id === selectedWorker)?.client_name || selectedWorker}
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <MetricChart
              key={`cpu-${selectedWorker}-${timeRange}`}
              title="Використання CPU"
              data={metricsData[selectedWorker]}
              dataKey="cpu_usage"
              color="#3b82f6"
              unit="%"
            />
            <MetricChart
              key={`memory-${selectedWorker}-${timeRange}`}
              title="Використання пам'яті"
              data={metricsData[selectedWorker]}
              dataKey="memory_usage"
              color="#10b981"
              unit="%"
            />
            <MetricChart
              key={`tasks-${selectedWorker}-${timeRange}`}
              title="Активні задачі"
              data={metricsData[selectedWorker]}
              dataKey="active_tasks"
              color="#f59e0b"
            />
            <MetricChart
              key={`response-${selectedWorker}-${timeRange}`}
              title="Час відповіді"
              data={metricsData[selectedWorker]}
              dataKey="response_time"
              color="#ef4444"
              unit="s"
            />
          </div>
        </div>
      )}

      {/* Worker selection */}
      {workers.length > 0 && (
        <div className="bg-white rounded-xl shadow-sm p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-4">
            Вибрати воркер для детального аналізу
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                         {workers.map(worker => (
               <button
                 key={`select-${worker.client_id}`}
                 onClick={() => handleWorkerSelect(worker.client_id)}
                 className={`p-4 rounded-lg border-2 transition-all text-left ${
                   selectedWorker === worker.client_id
                     ? 'border-primary-500 bg-primary-50'
                     : 'border-secondary-200 hover:border-secondary-300'
                 }`}
               >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-medium text-secondary-900">
                      {worker.client_name || worker.client_id}
                    </p>
                    <p className="text-sm text-secondary-600">
                      {worker.client_type === 'worker_api' ? 'API Worker' : 'Worker'}
                    </p>
                  </div>
                  <div className={`w-3 h-3 rounded-full ${
                    worker.connection_status === 'connected' ? 'bg-success-500' : 'bg-error-500'
                  }`} />
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export { WorkerMetrics };
